// TEST-332 — the generated code in the subject and level forms (CH-0372) and in the class, branch and room forms
// (CH-0373; a course's code is generated by the server since PORTAL-04-ADMIN-SIMPLIFY).
import { fireEvent, screen, waitFor } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'
import { ar } from '../i18n/ar'
import { BranchModal } from '../branches/BranchModal'
import { CreateClassModal } from '../classes/CreateClassModal'
import { RoomModal } from '../rooms/RoomModal'
import { jsonResponse, mockFetch } from '../test/http'
import { makeAuth, makeUser, renderWithProviders } from '../test/render'
import { LevelModal } from './LevelModal'
import { SubjectModal } from './SubjectModal'

const auth = makeAuth({ user: makeUser({ permissions: ['courses.read', 'courses.manage'] }) })

function codeField(): HTMLInputElement {
  return screen.getByPlaceholderText(/MATH|BEG/) as HTMLInputElement
}

describe('the generated code (CH-0372)', () => {
  it('fills a new subject with a SUB- code that is not taken, and «توليد رمز» draws another', async () => {
    const taken = ['MATH', 'SUB-AAAA']
    renderWithProviders(<SubjectModal open subject={null} onClose={vi.fn()} onSaved={vi.fn()} takenCodes={taken} />, { auth })
    const first = codeField().value
    expect(first).toMatch(/^SUB-[A-Z2-9]{4}$/)
    expect(taken).not.toContain(first)
    // The user may still type their own.
    fireEvent.change(codeField(), { target: { value: 'my-code' } })
    expect(codeField().value).toBe('MY-CODE')
    fireEvent.click(screen.getByText(ar.common.generateCode).closest('button')!)
    await waitFor(() => expect(codeField().value).toMatch(/^SUB-[A-Z2-9]{4}$/))
    expect(taken).not.toContain(codeField().value)
  })

  it('fills a new level with an LVL- code, and keeps the stored code of a level being edited', () => {
    renderWithProviders(<LevelModal open level={null} onClose={vi.fn()} onSaved={vi.fn()} takenCodes={['LVL-AAAA']} />, { auth })
    expect(codeField().value).toMatch(/^LVL-[A-Z2-9]{4}$/)
  })
})

describe('the generated code of a class, a branch and a room (CH-0373)', () => {
  it('opens each new one with its own prefix — longer for classes, whose list loads page by page', () => {
    mockFetch(() => jsonResponse(200, { items: [], nextCursor: null }))
    const klass = renderWithProviders(<CreateClassModal open onClose={vi.fn()} onCreated={vi.fn()} />, { auth })
    expect((screen.getByPlaceholderText('PY-101-A') as HTMLInputElement).value).toMatch(/^CLS-[A-Z2-9]{6}$/)
    klass.unmount()
    const branch = renderWithProviders(<BranchModal open branch={null} onClose={vi.fn()} onSaved={vi.fn()} takenCodes={['BR-AAAA']} />, { auth })
    expect((screen.getByPlaceholderText('MAIN') as HTMLInputElement).value).toMatch(/^BR-[A-Z2-9]{4}$/)
    branch.unmount()
    renderWithProviders(<RoomModal open room={null} branches={[]} onClose={vi.fn()} onSaved={vi.fn()} takenCodes={['RM-AAAA']} />, { auth })
    expect((screen.getByPlaceholderText('LAB-1') as HTMLInputElement).value).toMatch(/^RM-[A-Z2-9]{4}$/)
  })
})
